    hold_c_reference: 'Our worlds (fraud size set by hand)',
    hold_c_sample_fixed: 'Amounts of our phishing sample',
    hold_c_sample_prop: 'Same, other innocents paid in proportion to the fraud',
    hold_c_p2p: 'Sample amounts, {f} of frauds resell 20 % to one peer-to-peer buyer',
